import Router from 'vue-router';

const RemittanceLayout = () => import('@/containers/RemittanceLayout');
const OutwardRemittance = () => import('@/views/remittance/outwardRemittance/OutwardRemittance');
const CreateRecipientFlow = () => import('@/views/remittance/recipients/CreateRecipientFlow');

function configRoutes() {
  return [
    {
      path: '/remittances',
      component: RemittanceLayout,
      children: [
        {
          path: 'outwards',
          name: 'OutwardRemittance',
          component: OutwardRemittance,
          meta: { requiresAuth: true },
        },
        {
          path: 'recipients/create',
          name: 'CreateRecipient',
          component: CreateRecipientFlow,
          meta: { requiresAuth: true },
        },
      ],
    },
  ];
}

export default new Router({
  mode: 'history',
  routes: configRoutes(),
});

